insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-goodbug-gut-balance', 'The Good Bug Gut Balance SuperGut Stick', 'The Good Bug', 'supplement', 'physical', 'A daily synbiotic powder stick (probiotics plus prebiotic fiber) for gut and digestive health. The Good Bug says it eases bloating, gas and indigestion, supports regular digestion and immunity, and contains two of the most researched probiotic strains, Lacticaseibacillus rhamnosus LGG® and Bifidobacterium animalis subsp. lactis BB-12®, with an enzyme blend, vitamin C and inulin. The box lists 4 billion CFU. Mix one stick into 200 ml of water.', '$13 (list $14)', '/products/catalog/p-goodbug-gut-balance.webp', 'https://thegoodbug.com/products/healthy-gut-balance', '["goodbug","tgb","gut","gut health","probiotic","synbiotic","digestion","bloating","supplement"]'::jsonb, '["supplement"]'::jsonb, '["thegoodbug.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold in India as a nutraceutical (per the box). In the US this would be a dietary supplement, which the FDA does not evaluate for safety or efficacy claims.","materials":"Powder sticks, 1.2 g each; packs of 15, 30, 60 or 90. Made in India by Sundyota Numandis Probioceuticals for SevenTurns Private Limited. Best before 12 months from manufacture.","recalls":"No recalls found.","sideEffects":"Per The Good Bug, some people get mild bloating, gas or loose stools in the first few days; stop and see a doctor if it lasts more than 2 days. The Good Bug advises checking with a health practitioner first if you are pregnant or breastfeeding, or have IBS, diabetes or another medical condition. Full warnings are listed below.","opinionAlerts":"Ingredient mismatch: The Good Bug''s description and box name the strains LGG® and BB-12®, but the ingredient list on the same page names different strains (L. plantarum UALp-05 and B. lactis UABla-12) and no enzymes or vitamin C. It may be from the older formula; check the box you receive."}'::jsonb, 'The Good Bug says Gut Balance eases bloating, gas and indigestion, and supports digestion and immunity, using LGG® and BB-12®, two well-studied probiotic strains. No independent study of this product was found.

For LGG, a 2025 meta-analysis of 69 randomized trials found it reduced the risk and length of diarrhea, with moderate-certainty evidence that was strongest in children. Its effects on bloating, abdominal pain and constipation were limited, and the authors said evidence in adults was limited.

The Good Bug cites two studies. The first, a 2015 randomized, double-blind, placebo-controlled trial of 650 people in Croatia, gave the same two strains (LGG® and BB-12®) or a placebo for 14 days alongside antibiotics for an H. pylori stomach infection. The probiotic group had a higher cure rate (87% vs 73%) and less bloating, flatulence and other treatment side effects. Those were people on antibiotics, not people with everyday bloating, and two authors worked for JGL, the company that sells that probiotic. The second, a 2024 study of 20 healthy adults with post-meal bloating, found that a single dose of a different company''s supplement (18 digestive enzymes plus ginger, fennel and peppermint) reduced belly distension after one meal compared with a placebo. It was funded by HUM Nutrition, whose employee wrote it, and Gut Balance''s enzyme blend doesn''t include those herbs.

One thing to check: the ingredient list on The Good Bug''s own page names different strains (L. plantarum UALp-05 and B. lactis UABla-12) than its description and box (LGG® and BB-12®). Research on one strain doesn''t carry over to another, so it matters which formula you get.', 'The Good Bug''s product page shows 4.6 out of 5 stars from 119 reviews: 68% five stars, 22% four stars, 8% three stars and 2% two stars. The first reviews shown describe less bloating and acidity and better digestion after a few weeks or months. These are reviews on the brand''s own site; no independent review data was found at time of writing.', 'LGG reduced diarrhea in many trials, mostly in children; effects on bloating and constipation were limited.', 'brand', 'Product claims are sourced from The Good Bug; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"ingredients":"Per The Good Bug''s description and the box: L. rhamnosus LGG®, B. lactis BB-12®, enzyme blend (amylase, cellulase, lipase, lactase, protease), vitamin C, inulin; 4 billion CFU. The ingredient list on the same product page instead reads: Isomalt, Hydrolyzed Guar Gum, Polydextrose, Fructooligosaccharides, Lactobacillus Plantarum UALp-05, Bifidobacterium lactis UABla-12, Added Flavors (Nature Identical Flavors), Permitted Natural Color (INS 160a). 1.2 g per stick.","doctorOpinionShort":"Its main strain, LGG, reduces diarrhea in a large body of trials, mostly in children, but did little for bloating or constipation in a 2025 meta-analysis. The trial The Good Bug cites found less bloating only in people taking antibiotics for H. pylori. The product page lists different strains in its ingredient list than in its description, so check the box. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://thegoodbug.com/products/healthy-gut-balance","label":"thegoodbug.com: Gut Balance, ingredients and claims"},{"url":"https://pubmed.ncbi.nlm.nih.gov/40702885/","label":"PubMed: Effects of Lacticaseibacillus rhamnosus GG on gastrointestinal and respiratory outcomes, systematic review and meta-analysis (2025)","chipLabel":"LGG meta-analysis, 69 trials (2025)"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4603068/","label":"NIH (PMC): Probiotics for standard triple Helicobacter pylori eradication, randomized, double-blind, placebo-controlled trial (Hauser et al., 2015)","chipLabel":"H. pylori probiotic trial, 650 people (2015)"},{"url":"https://doi.org/10.2147/NDS.S453377","label":"Nutrition and Dietary Supplements (2024): A multi-digestive enzyme and herbal dietary supplement reduces bloating in a single use in healthy adults","chipLabel":"Enzyme + herbal bloating study, 20 people (2024)"}],"whoItsFor":["Adults looking for a daily probiotic powder for general digestive support","People who prefer a stick mixed into water over capsules","Not a substitute for seeing a doctor about persistent bloating, diarrhea or changes in bowel habits"],"howToUse":{"intro":"The Good Bug sizes its packs at one stick a day (15 sticks for 15 days, 30 for a month) and says the best results came with 3 months of consistent use.","steps":["Mix one stick into 200 ml of water.","Avoid mixing it into carbonated drinks like soda.","If you miss a dose, take it when you remember; don''t double up."],"sourceUrl":"https://thegoodbug.com/products/healthy-gut-balance","sourceLabel":"thegoodbug.com: Gut Balance"},"warnings":["Pregnant, breastfeeding, or managing IBS, diabetes or another medical condition: check with a doctor first (per The Good Bug).","Loose stools or digestive changes lasting more than 2 days: stop and see a doctor (per The Good Bug)."],"ingredientScience":[{"name":"LGG® + BB-12® with antibiotics (study cited by The Good Bug)","text":"In a 2015 randomized, double-blind, placebo-controlled trial, 650 people taking standard antibiotic therapy for an H. pylori stomach infection also took LGG® and BB-12® (10⁸ to 10¹⁰ live bacteria per capsule) or a placebo, twice a day for 14 days. The probiotic group had a higher cure rate (87% vs 73%) and fewer treatment side effects, including less bloating and flatulence, in 7 of 10 tracked symptoms. Participants were on antibiotics, not people with everyday bloating, and two of the authors worked for JGL, which sells that probiotic.","citations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4603068/","label":"NIH (PMC): Probiotics for standard triple Helicobacter pylori eradication, randomized, double-blind, placebo-controlled trial (Hauser et al., Medicine 2015)"}]},{"name":"Digestive enzymes (study cited by The Good Bug)","text":"In a 2024 double-blind, placebo-controlled crossover study, 20 healthy adults with daily post-meal bloating took a single dose of a supplement with 18 digestive enzymes plus ginger, fennel and peppermint, or a placebo, before a test meal, then switched after a one-week washout. The supplement reduced waist distension by 58% at 30 minutes and 68% at 90 minutes compared with placebo. The study tested HUM Nutrition''s product, was funded by HUM, and its author worked there. Gut Balance''s enzyme blend doesn''t include the herbs.","citations":[{"url":"https://doi.org/10.2147/NDS.S453377","label":"Nutrition and Dietary Supplements (2024): A multi-digestive enzyme and herbal dietary supplement reduces bloating in a single use in healthy adults"}]},{"name":"Lacticaseibacillus rhamnosus GG (LGG)","text":"The Good Bug calls this the world''s most studied probiotic. A 2025 meta-analysis of 69 randomized trials found LGG reduced the risk of diarrhea and shortened it, with moderate-certainty evidence that was more consistent in children. It had limited effects on bloating, abdominal pain, constipation and nausea, and the authors said evidence in adults was limited.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/40702885/","label":"PubMed: Effects of Lacticaseibacillus rhamnosus GG on gastrointestinal and respiratory outcomes, systematic review and meta-analysis (2025)"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://thegoodbug.com/products/healthy-gut-balance","text":"thegoodbug.com: Gut Balance customer reviews","summary":"The Good Bug''s own product page shows 4.6 out of 5 stars from 119 reviews."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-goodbug-good-to-glow', 'The Good Bug Good To Glow SuperGut Stick', 'The Good Bug', 'supplement', 'physical', 'A daily synbiotic powder stick for skin, hair and nails "from within". It combines the probiotic Lactobacillus plantarum (5 billion CFU, per the box) with glutathione, trans-resveratrol, vitamin C, vitamin A, zinc, biotin, lycopene and inulin, in a berry flavor. The Good Bug says it brightens and hydrates skin, helps with sun damage, blemishes, dark spots and wrinkles, and strengthens hair and nails.', '$13 (list $14)', '/products/catalog/p-goodbug-good-to-glow.webp', 'https://thegoodbug.com/products/good-to-glow', '["goodbug","tgb","skin","hair","nails","probiotic","synbiotic","glutathione","beauty supplement","supplement"]'::jsonb, '["supplement","skin-hair"]'::jsonb, '["thegoodbug.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold in India as a nutraceutical (per the box). In the US this would be a dietary supplement, which the FDA does not evaluate for safety or efficacy claims.","materials":"Powder sticks, 3 g each; packs of 15, 30, 60 or 90. Sweetened with xylitol, sorbitol and stevia. The Good Bug doesn''t list amounts of glutathione, vitamins or other actives. Made in India by Sundyota Numandis Probioceuticals for SevenTurns Private Limited. Best before 24 months from manufacture.","recalls":"No recalls found.","sideEffects":"The Good Bug says it isn''t recommended for children, or for pregnant or breastfeeding women or anyone with a medical condition without checking with a healthcare professional first. It contains biotin, which the FDA warns can interfere with certain lab tests, so tell your doctor you take it before blood work. It also contains sugar alcohols (xylitol, sorbitol). Full warnings are listed below.","opinionAlerts":"Skin claims come from The Good Bug, and no independent study of this product was found. The Good Bug doesn''t list how much glutathione or vitamins each stick contains."}'::jsonb, 'The Good Bug says Good To Glow brightens and hydrates skin, helps with sun damage, blemishes and dark spots, reduces the look of wrinkles, and strengthens hair and nails. No independent study of this product was found, so what follows is what the research says about its main ingredients.

Glutathione has the most direct evidence. In a randomized, double-blind, placebo-controlled trial of 60 medical students in Thailand, 500 mg a day of oral glutathione for 4 weeks lightened skin at two of six measured sites compared with placebo. A 2024 systematic review found oral glutathione at 250–500 mg a day reduced the skin''s melanin index in five randomized trials, but called the results unsustainable and noted long-term safety isn''t established. The Good Bug doesn''t list how much glutathione each stick contains.

For Lactobacillus plantarum, the human evidence found was for a different form: in a Korean study, candy containing dead-bacteria fragments (lysate) of one specific strain, L. plantarum K8, improved skin hydration over 8 weeks compared with plain candy. Good To Glow''s label doesn''t name its strain, and it uses live bacteria, so that result may not apply.', 'The Good Bug''s product page shows 4.3 out of 5 stars from 1,623 reviews: 36% five stars, 61% four stars, 2% three stars, and two one-star reviews. The first reviews shown describe brighter, glowing skin after about a month, for example: "within a month of using it, people started telling me that my skin is glowing." These are reviews on the brand''s own site; no independent review data was found at time of writing.', 'Oral glutathione lightened skin in small randomized trials; the probiotic''s skin evidence comes from a different form and strain.', 'brand', 'Product claims are sourced from The Good Bug; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"ingredients":"Full ingredient list per The Good Bug: Stabilizer [Xylitol (INS 967)], Sweetener [Sorbitol (INS 420(i))], Glutathione, Zinc Gluconate, Vitamin C, Lactobacillus plantarum, Trans Resveratrol, Inulin, Lycopene, Sweetener [Steviol Glycoside (INS 960)], Anti-Sticking Agent [Magnesium Stearate (INS 470(iii))], Vitamin A, Biotin. Contains added berry flavor. 3 g per stick; 5 billion CFU per the box.","doctorOpinionShort":"Oral glutathione lightened skin in small randomized trials, but long-term safety isn''t established and this product doesn''t list its dose. Evidence for its probiotic comes from a different form and strain. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://thegoodbug.com/products/good-to-glow","label":"thegoodbug.com: Good To Glow, ingredients and claims"},{"url":"https://pubmed.ncbi.nlm.nih.gov/20524875/","label":"PubMed: Glutathione as an oral whitening agent, randomized, double-blind, placebo-controlled study","chipLabel":"Oral glutathione trial, 60 people (2012)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/39444151/","label":"PubMed: Glutathione as a skin-lightening agent and in melasma, systematic review","chipLabel":"Glutathione systematic review (2024)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/25179904/","label":"PubMed: Effects of oral intake of kimchi-derived Lactobacillus plantarum K8 lysates on skin moisturizing","chipLabel":"L. plantarum K8 skin study (2015)"}],"whoItsFor":["Adults interested in an ingestible skin, hair and nail supplement alongside their skincare","People who prefer a flavored powder stick over capsules","Not for children, or during pregnancy or breastfeeding without checking with a clinician (per The Good Bug)"],"howToUse":{"intro":"The Good Bug sizes its packs at one stick a day (15 sticks for 15 days, 30 for a month). Its Good To Glow page doesn''t give mixing directions.","steps":["Take one stick a day.","Keep using sunscreen daily; The Good Bug''s own page recommends it alongside the product."],"sourceUrl":"https://thegoodbug.com/products/good-to-glow","sourceLabel":"thegoodbug.com: Good To Glow"},"warnings":["Pregnant, breastfeeding, or managing a medical condition: check with a doctor first (per The Good Bug). Not for children.","Contains biotin: the FDA warns biotin can interfere with certain lab tests, so tell your doctor before blood work."],"ingredientScience":[{"name":"Glutathione (oral)","text":"The Good Bug states this brightens skin. In a randomized, double-blind, placebo-controlled trial of 60 people, 500 mg a day of oral glutathione for 4 weeks lightened skin at two of six measured sites (the face and a sun-exposed forearm) compared with placebo. A 2024 systematic review found five randomized trials where oral glutathione at 250–500 mg a day reduced the melanin index, but described the effect as unsustainable. Long-term safety isn''t established. This product''s glutathione amount isn''t listed.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20524875/","label":"PubMed: Glutathione as an oral whitening agent, randomized, double-blind, placebo-controlled study (2012)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/39444151/","label":"PubMed: Glutathione as a skin-lightening agent and in melasma, systematic review (2024)"}]},{"name":"Lactobacillus plantarum","text":"The Good Bug states this revitalizes skin. In a Korean study, people who ate candy containing 2.1% dead-bacteria fragments (lysate) of L. plantarum strain K8 had better skin hydration after 4 and 8 weeks than people eating the same candy without it. Good To Glow uses live L. plantarum of an unnamed strain, so that result may not apply.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25179904/","label":"PubMed: Effects of oral intake of kimchi-derived Lactobacillus plantarum K8 lysates on skin moisturizing (2015)"}]}],"scientificCitations":[{"url":"https://www.fda.gov/medical-devices/in-vitro-diagnostics/biotin-interference-troponin-lab-tests-assays-subject-biotin-interference","text":"FDA: Biotin interference with lab tests","summary":"The FDA says biotin, often found in dietary supplements, can significantly interfere with certain lab tests and cause incorrect results that may go undetected."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://thegoodbug.com/products/good-to-glow","text":"thegoodbug.com: Good To Glow customer reviews","summary":"The Good Bug''s own product page shows 4.3 out of 5 stars from 1,623 reviews."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-goodbug-good-down-there', 'The Good Bug Good Down There Vaginal Health Stick', 'The Good Bug', 'supplement', 'physical', 'A daily powder stick for vaginal and urinary health. It combines four Lactobacillus species (L. crispatus, L. gasseri, L. jensenii and L. rhamnosus) with D-mannose, cranberry extract, zinc, vitamin C and inulin, in a cranberry flavor. The Good Bug says it promotes a healthy vaginal pH, balances good bacteria, supports urinary tract health and helps reduce UTI recurrence. The page says it is not designed to treat UTIs, BV or yeast infections. Sold in packs of 15, 30, 60 or 90 sticks.', '$14 (15 sticks)', 'https://cdn.shopify.com/s/files/1/0657/8225/1745/products/GoodDownThere_3.jpg?width=500', 'https://thegoodbug.com/products/good-down-there-for-vaginal-health', '["goodbug","tgb","vaginal health","probiotic","synbiotic","cranberry","d-mannose","uti","ph balance","supplement"]'::jsonb, '["vaginal-health","supplement"]'::jsonb, '["thegoodbug.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold in India as a nutraceutical; the product page lists an FSSAI license. In the US this would be a dietary supplement, which the FDA does not evaluate for safety or efficacy. The page shows a \"US FDA Licensed\" badge; the FDA does not license or approve dietary supplements, and ayna found no FDA record for this product.","materials":"Powder sticks; packs of 15, 30, 60 or 90. Sweetened with sorbitol, xylitol and stevia. Made in India by Sundyota Numandis Probioceuticals for SevenTurns Private Limited, Mumbai. Best before 18 months from manufacture. The page leaves the net quantity blank.","recalls":"No recalls found.","sideEffects":"The Good Bug says to check with a healthcare practitioner first if you are pregnant or breastfeeding, take prescription medicine for a neurological condition, have allergies to any ingredient, or recently had surgery. It contains sugar alcohols (sorbitol, xylitol). Full warnings are listed below.","opinionAlerts":"The page names four Lactobacillus species but no strain codes or CFU, and gives no amounts for D-mannose or cranberry, so it can''t be matched to published trials. It also says D-mannose is more effective than antibiotics at preventing repeat infections; no source is given, and a 598-woman placebo-controlled trial found D-mannose did not prevent repeat UTIs. No study of this product was found."}'::jsonb, 'The Good Bug says Good Down There promotes a healthy vaginal pH, balances good bacteria, supports urinary tract health and helps reduce UTI recurrence. No study of this product was found, and the page doesn''t cite one.

The probiotic part can''t be checked against research. L. crispatus, L. gasseri, L. jensenii and L. rhamnosus are species found in a healthy vagina, but the page lists no strain codes and no CFU count. NIH notes that the effects of a probiotic depend on the specific strain: one kind of Lactobacillus helping doesn''t mean another will.

For the urinary claims, the evidence on the two other actives points in different directions. A 2023 Cochrane review of 50 trials (8,857 people) found cranberry products probably lower the risk of symptomatic, culture-confirmed UTIs in women with recurrent UTIs (8 trials, 1,555 women), with moderate-certainty evidence overall. For D-mannose, a 2024 double-blind, placebo-controlled trial of 598 women with recurrent UTIs across 99 UK primary care practices found 2 g a day for 6 months did not reduce repeat UTIs (51% vs 56%, not a significant difference), and the authors said it should not be recommended for prevention in that group. The page doesn''t list how much cranberry or D-mannose each stick contains.', 'The Good Bug''s product page shows 4.3 out of 5 stars from 1,629 reviews. The first reviews shown talk about glowing skin, stronger nails and PCOS symptoms rather than vaginal or urinary health, so the reviews may be pooled across the brand''s products. These are reviews on the brand''s own site; no independent review data was found at time of writing.', 'No study of this product was found. Cranberry products probably lower repeat UTIs in women prone to them; D-mannose did not in a 598-woman trial. The probiotic strains are not named, so their effect is unknown.', 'independent', 'ayna summary of NIH (NCCIH) information on probiotics and peer-reviewed research on cranberry and D-mannose. Not a direct clinician quote; none of the studies tested this product.', 'curated', false, false, null, true, '{"ingredients":"Full ingredient list per The Good Bug: Sweetener [Sorbitol (INS 420(i))], Stabilizer [Xylitol (INS 967)], D-Mannose, Cranberry Extract, Lactobacillus crispatus, Lactobacillus gasseri, Lactobacillus jensenii (spelled \"jenseni\" in the list), Lactobacillus rhamnosus, Zinc Gluconate, Vitamin C, Inulin, Acidity Regulator [Citric Acid (INS 330)], Sweetener [Steviol Glycoside (INS 960)], Anti-Sticking Agent [Magnesium Stearate (INS 470(iii))]. Added cranberry flavor. The page doesn''t give strain codes, CFU, or the amount of D-mannose, cranberry or any other ingredient.","doctorOpinionShort":"Cranberry products probably lower repeat UTIs in women prone to them, but a large 2024 trial found D-mannose did not. The probiotic species are vaginal ones, but no strain codes or CFU are given, so they can''t be matched to research. No study of this product was found.","doctorOpinionCitations":[{"url":"https://thegoodbug.com/products/good-down-there-for-vaginal-health","label":"thegoodbug.com: Good Down There, ingredients and claims"},{"url":"https://pubmed.ncbi.nlm.nih.gov/37068952/","label":"PubMed: Cranberries for preventing urinary tract infections, Cochrane review (2023)","chipLabel":"Cranberry Cochrane review, 50 trials (2023)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/38587819/","label":"PubMed: d-Mannose for prevention of recurrent urinary tract infection among women, randomized clinical trial (JAMA Intern Med, 2024)","chipLabel":"D-mannose trial, 598 women (2024)"},{"url":"https://www.nccih.nih.gov/health/probiotics-usefulness-and-safety","label":"NIH (NCCIH): Probiotics, usefulness and safety"}],"whoItsFor":["Adults who want a daily powder aimed at vaginal and urinary health","People who prefer a stick mixed into water over capsules","Not a treatment for an active UTI, BV or yeast infection: see a clinician if you have symptoms"],"howToUse":{"intro":"The Good Bug sizes its packs at one stick a day (15 sticks for 15 days, 30 for a month). The product page doesn''t give mixing directions; its other sticks are mixed into water, so check the box.","steps":["Take one stick a day, going by the pack sizes.","The Good Bug also suggests fiber, plenty of water, less sugar and refined carbs, wiping front to back and urinating after sex."],"sourceUrl":"https://thegoodbug.com/products/good-down-there-for-vaginal-health","sourceLabel":"thegoodbug.com: Good Down There"},"warnings":["Pregnant or breastfeeding, taking prescription medicine for a neurological condition, allergic to any ingredient, or recently had surgery: check with a doctor first (per The Good Bug).","Not a treatment for a UTI, BV or yeast infection (per The Good Bug). See a clinician for burning, unusual discharge, odor or fever.","Contains sugar alcohols (sorbitol, xylitol), which can loosen stools in some people."],"ingredientScienceNote":"These studies tested cranberry and D-mannose on their own, not this product. The page doesn''t give amounts, so it isn''t known whether a stick matches the doses studied.","ingredientScience":[{"name":"Cranberry","text":"A 2023 Cochrane review of 50 randomized trials (8,857 people) found cranberry products reduced symptomatic, culture-confirmed UTIs overall (moderate-certainty evidence). In women with recurrent UTIs (8 trials, 1,555 women) they probably lowered the risk by about a quarter. They showed little or no benefit in pregnant women or older adults in care homes. Stomach side effects were similar to placebo.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/37068952/","label":"PubMed: Cranberries for preventing urinary tract infections (Cochrane Database Syst Rev, 2023)"}]},{"name":"D-mannose","text":"In a 2024 double-blind, placebo-controlled trial at 99 UK primary care practices, 598 women with recurrent UTIs took 2 g of D-mannose powder or a placebo daily for 6 months. 51% of the D-mannose group and 56% of the placebo group saw a doctor for a suspected UTI, a difference that was not statistically significant, and no secondary outcome differed. The authors concluded D-mannose should not be recommended for UTI prevention in this group.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/38587819/","label":"PubMed: d-Mannose for prevention of recurrent UTI among women, randomized clinical trial (JAMA Intern Med, 2024)"}]},{"name":"Why the strain matters","text":"NIH notes that different probiotics can have different effects: if one kind of Lactobacillus helps, that doesn''t mean another kind will do the same. Good Down There lists species (L. crispatus, L. gasseri, L. jensenii, L. rhamnosus) but no strain codes, so no study can be matched to it.","citations":[{"url":"https://www.nccih.nih.gov/health/probiotics-usefulness-and-safety","label":"NIH (NCCIH): Probiotics, usefulness and safety"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://pubmed.ncbi.nlm.nih.gov/37068952/","text":"Cranberries for preventing UTIs (Cochrane, 2023)","summary":"50 trials; probably fewer repeat UTIs in women prone to them.","justification":"Conservative ayna classification: category or adjacent evidence only; this source does not validate this specific product."},{"url":"https://pubmed.ncbi.nlm.nih.gov/38587819/","text":"D-mannose for recurrent UTI, randomized trial (2024)","summary":"598 women; no reduction in repeat UTIs vs placebo.","justification":"Conservative ayna classification: category or adjacent evidence only; this source does not validate this specific product."}]},"community":{"links":[{"platform":"website","url":"https://thegoodbug.com/products/good-down-there-for-vaginal-health","text":"thegoodbug.com: Good Down There customer reviews","summary":"The Good Bug''s own product page shows 4.3 out of 5 stars from 1,629 reviews; the reviews shown first are about skin and nails, so they may be pooled across products."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb)
